<?php
require_once __DIR__.'/conexion.php';
require_once __DIR__.'/tipo_movimiento.php';
class movimiento
{
    private PDO $db;
    public function __construct(?PDO $db=null){$this->db=$db??(new conexion())->con();}
    private function q(string $sql,array $p=[]): PDOStatement {$s=$this->db->prepare($sql);$s->execute($p);return $s;}
    private function fecha(string $v): string {$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new InvalidArgumentException('Selecciona una fecha válida.');return $v;}
    private function texto($v,int $max,string $label): string {$v=trim((string)$v);if(mb_strlen($v)>$max)throw new InvalidArgumentException("$label supera $max caracteres.");return $v;}
    private function decimal($v,int $precision,bool $positivo): float {if(!is_numeric($v)||!is_finite((float)$v)||(float)$v<0||($positivo&&(float)$v<=0)||(float)$v>99999999||abs((float)$v-round((float)$v,$precision))>0.000001)throw new InvalidArgumentException('Revisa los montos y cantidades; precio con dos decimales y cantidad con hasta tres.');return round((float)$v,$precision);}
    private function clave($v): string {$v=(string)$v;if(!preg_match('/^[a-f0-9]{32}$/',$v))throw new InvalidArgumentException('Actualiza la página antes de registrar.');return $v;}
    private function activa(array $c): void {if((int)$c['com_estado']!==1)throw new InvalidArgumentException('El movimiento está anulado.');}
    public function listar(int $loc,string $inicio='',string $fin=''): array {
        $w='m.loc_id=?';$p=[$loc];if($inicio!==''){$w.=' AND m.mov_fecha>=?';$p[]=$this->fecha($inicio);}if($fin!==''){$w.=' AND m.mov_fecha<=?';$p[]=$this->fecha($fin);}if($inicio&&$fin&&$inicio>$fin)throw new InvalidArgumentException('Revisa el rango de fechas.');
        return $this->q("SELECT m.mov_id com_id,m.mov_tipo movimiento_tipo,m.mov_fecha com_fecha,m.mov_tipo_doc com_tipo_doc,m.mov_serie com_serie,m.mov_correlativo com_correlativo,m.mov_total com_total,m.mov_estado com_estado,COALESCE(e.ent_nombres,d.tipos,'Sin detalle') proveedor,COALESCE(p.pagado,0) pagado,GREATEST(m.mov_total-COALESCE(p.pagado,0),0) saldo FROM movimiento m LEFT JOIN entidad e ON e.ent_id=m.ent_id LEFT JOIN (SELECT mov_id,SUM(mpa_monto) pagado FROM movimiento_pago WHERE mpa_estado=1 GROUP BY mov_id) p ON p.mov_id=m.mov_id LEFT JOIN (SELECT md.mov_id,GROUP_CONCAT(DISTINCT t.tmc_nombre ORDER BY t.tmc_nombre SEPARATOR ', ') tipos FROM movimiento_detalle md JOIN tipo_movimiento t ON t.tmc_id=md.tmc_id GROUP BY md.mov_id) d ON d.mov_id=m.mov_id WHERE $w ORDER BY m.mov_fecha DESC,m.mov_id DESC",$p)->fetchAll();
    }
    public function perteneceAlLocal(int $id,int $loc): bool {return (bool)$this->q('SELECT 1 FROM movimiento WHERE mov_id=? AND loc_id=?',[$id,$loc])->fetchColumn();}
    public function obtener(int $id,bool $lock=false): array {
        $c=$this->q("SELECT m.mov_id com_id,m.loc_id,m.mov_tipo movimiento_tipo,m.ent_id,m.mov_tipo_doc com_tipo_doc,m.mov_serie com_serie,m.mov_correlativo com_correlativo,m.mov_fecha com_fecha,m.mov_subtotal com_subtotal,m.mov_igv com_igv,m.mov_total com_total,m.mov_observaciones com_observaciones,m.mov_incluye_igv com_incluye_igv,m.mov_estado com_estado,e.ent_nombres proveedor,e.ent_nro_doc FROM movimiento m LEFT JOIN entidad e ON e.ent_id=m.ent_id WHERE m.mov_id=?".($lock?' FOR UPDATE':''),[$id])->fetch();if(!$c)throw new InvalidArgumentException('El movimiento no existe.');
        $detalle=$this->q('SELECT mde_id cde_id,mov_id com_id,tmc_id cco_id,mde_nombre cde_nombre,mde_unidad cde_und_med,mde_precio_unitario cde_prec_unit,mde_cantidad cde_cantidad,mde_subtotal cde_subtotal FROM movimiento_detalle WHERE mov_id=? ORDER BY mde_id',[$id])->fetchAll();
        $pagos=$this->q('SELECT p.mpa_id cop_id,p.mov_id com_id,p.mpa_fecha cop_fecha,p.tpa_id,p.mpa_medio cop_forma_pago,p.mpa_numero_operacion cop_numero_operacion,p.cba_id,p.mpa_monto cop_monto,p.mpa_estado cop_estado,b.cba_banco,b.cba_numero,b.cba_moneda FROM movimiento_pago p LEFT JOIN cuenta_bancaria b ON b.cba_id=p.cba_id WHERE p.mov_id=? AND p.mpa_estado=1 ORDER BY p.mpa_id',[$id])->fetchAll();
        $docs=$this->q('SELECT mdo_id cdo_id,mdo_nombre cdo_nombre,mdo_mime cdo_mime,mdo_tamano cdo_tamano FROM movimiento_documento WHERE mov_id=? AND mdo_estado=1 ORDER BY mdo_id',[$id])->fetchAll();
        return ['movimiento'=>$c,'detalle'=>$detalle,'pagos'=>$pagos,'documentos'=>$docs,'version'=>hash('sha256',json_encode([$c,$detalle]))];
    }
    public function opciones(): array {return ['proveedores'=>$this->q('SELECT ent_id,ent_nombres,ent_nro_doc FROM entidad WHERE ent_estado=1 AND ent_proveedor=1 ORDER BY ent_nombres')->fetchAll(),'conceptos'=>$this->q('SELECT tmc_id cco_id,tmc_nombre cco_nombre,tmc_clase cco_clase,tmc_unidad cco_unidad,tmc_tipo FROM tipo_movimiento WHERE tmc_estado=1 ORDER BY tmc_tipo,tmc_nombre')->fetchAll(),'metodos'=>$this->q('SELECT tpa_id,tpa_nombre FROM tipo_pago WHERE tpa_estado=1 ORDER BY tpa_nombre')->fetchAll(),'cuentas'=>$this->q("SELECT * FROM cuenta_bancaria WHERE cba_estado=1 AND cba_moneda='PEN' ORDER BY cba_banco")->fetchAll()];}
    public function guardar(int $loc,int $usu,array $d): int {
        $id=(int)($d['com_id']??0);$movTipo=strtoupper((string)($d['mov_tipo']??'EGRESO'));if(!in_array($movTipo,['INGRESO','EGRESO'],true))throw new InvalidArgumentException('Selecciona ingreso o egreso.');$ent=(int)($d['ent_id']??0);$fecha=$this->fecha((string)($d['com_fecha']??''));$tipo=$movTipo==='INGRESO'?'00':(string)($d['com_tipo_doc']??'');if(!in_array($tipo,['01','03','00'],true))throw new InvalidArgumentException('Selecciona Factura, Boleta o Sin comprobante.');
        $serie=strtoupper($this->texto($d['com_serie']??'',4,'Serie'));$numero=$this->texto($d['com_correlativo']??'',20,'Número');if($tipo==='00'){$serie='';$numero='';}elseif(!preg_match('/^[A-Z0-9]{1,4}$/',$serie)||!preg_match('/^\d{1,20}$/',$numero))throw new InvalidArgumentException('Ingresa serie y número de comprobante válidos.');
        $obs=$this->texto($d['com_observaciones']??'',3000,'Observaciones');$igv=$movTipo==='EGRESO'&&$tipo!=='00';$items=$d['items']??[];if(!is_array($items)||!count($items)||count($items)>500)throw new InvalidArgumentException('Agrega entre 1 y 500 tipos de movimiento.');
        $rows=[];$total=0;$seen=[];foreach($items as $item){$tmc=(int)($item['cco_id']??$item['tmc_id']??0);if(!$tmc||isset($seen[$tmc]))throw new InvalidArgumentException('Selecciona tipos activos y no los repitas.');$seen[$tmc]=true;$concepto=$this->q('SELECT tmc_nombre,tmc_unidad FROM tipo_movimiento WHERE tmc_id=? AND tmc_tipo=? AND tmc_estado=1',[$tmc,$movTipo])->fetch();if(!$concepto)throw new InvalidArgumentException('Uno de los tipos no corresponde al movimiento o ya no está habilitado.');$nombre=$concepto['tmc_nombre'];$und=$concepto['tmc_unidad'];$cantidad=$this->decimal($item['cantidad']??null,3,true);$precio=$this->decimal($item['precio']??null,2,false);$sub=(int)round($cantidad*$precio*100);$total+=$sub;if($total>99999999999999)throw new InvalidArgumentException('El total supera el límite permitido.');$rows[]=[$tmc,$nombre,$und,$precio,$cantidad,$sub/100];}if($total<=0)throw new InvalidArgumentException('El total debe ser mayor que cero.');$clave=$id?null:$this->clave($d['clave']??'');
        $this->db->beginTransaction();try {
            if(!$id){$ex=$this->q('SELECT mov_id FROM movimiento WHERE mov_clave=?',[$clave])->fetchColumn();if($ex){$this->db->commit();return (int)$ex;}}
            if($id){$r=$this->obtener($id,true);$this->activa($r['movimiento']);if(!hash_equals($r['version'],(string)($d['version']??'')))throw new InvalidArgumentException('El movimiento cambió. Vuelve a abrirlo antes de editar.');if(count($r['pagos']))throw new InvalidArgumentException('Anula los pagos registrados antes de modificar el movimiento.');$movTipo=$r['movimiento']['movimiento_tipo'];}
            if($movTipo==='EGRESO'&&!$this->q('SELECT ent_id FROM entidad WHERE ent_id=? AND ent_proveedor=1 AND ent_estado=1 FOR UPDATE',[$ent])->fetchColumn())throw new InvalidArgumentException('Selecciona una entidad activa marcada como proveedor.');if($movTipo==='INGRESO')$ent=0;
            if($tipo!=='00'&&$this->q("SELECT COUNT(*) FROM movimiento WHERE mov_tipo='EGRESO' AND ent_id=? AND mov_tipo_doc=? AND mov_serie=? AND mov_correlativo=? AND mov_estado=1 AND mov_id<>?",[$ent,$tipo,$serie,$numero,$id])->fetchColumn())throw new InvalidArgumentException('Ese comprobante ya está registrado para el proveedor.');
            $base=$igv?round($total/1.18)/100:$total/100;$tax=$total/100-$base;
            $values=[$movTipo,$rows[0][0],$ent?:null,$tipo,$serie,$numero,$fecha,$base,$tax,$total/100,$obs,(int)$igv];
            if($id){$this->q('UPDATE movimiento SET mov_tipo=?,tmc_id=?,ent_id=?,mov_tipo_doc=?,mov_serie=?,mov_correlativo=?,mov_fecha=?,mov_subtotal=?,mov_igv=?,mov_total=?,mov_observaciones=?,mov_incluye_igv=?,mov_usuario_edicion=?,mov_fecha_edicion=NOW() WHERE mov_id=?',array_merge($values,[$usu,$id]));$this->q('DELETE FROM movimiento_detalle WHERE mov_id=?',[$id]);}
            else{$this->q('INSERT INTO movimiento(loc_id,mov_tipo,tmc_id,ent_id,mov_tipo_doc,mov_serie,mov_correlativo,mov_fecha,mov_subtotal,mov_igv,mov_total,mov_observaciones,mov_incluye_igv,mov_usuario_creacion,mov_clave) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',array_merge([$loc],$values,[$usu,$clave]));$id=(int)$this->db->lastInsertId();}
            foreach($rows as $row)$this->q('INSERT INTO movimiento_detalle(mov_id,tmc_id,mde_nombre,mde_unidad,mde_precio_unitario,mde_cantidad,mde_subtotal) VALUES(?,?,?,?,?,?,?)',array_merge([$id],$row));$this->db->commit();return $id;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function pagar(int $usu,array $d): void {
        $id=(int)($d['com_id']??0);$fecha=$this->fecha((string)($d['cop_fecha']??''));$monto=$this->decimal($d['cop_monto']??null,2,true);$clave=$this->clave($d['clave']??'');$op=$this->texto($d['cop_numero_operacion']??'',50,'Operación');$tpa=(int)($d['tpa_id']??0);$cba=(int)($d['cba_id']??0);
        $this->db->beginTransaction();try {$r=$this->obtener($id,true);$this->activa($r['movimiento']);$ex=$this->q('SELECT mov_id FROM movimiento_pago WHERE mpa_clave=?',[$clave])->fetchColumn();if($ex){if((int)$ex!==$id)throw new InvalidArgumentException('Solicitud de pago inválida.');$this->db->commit();return;}
            $tipo=$this->q('SELECT tpa_nombre FROM tipo_pago WHERE tpa_id=? AND tpa_estado=1',[$tpa])->fetchColumn();if(!$tipo)throw new InvalidArgumentException('Selecciona un método de pago activo.');if(!$this->q("SELECT COUNT(*) FROM cuenta_bancaria WHERE cba_id=? AND cba_estado=1 AND cba_moneda='PEN'",[$cba])->fetchColumn())throw new InvalidArgumentException('Selecciona una cuenta activa en soles.');
            $pagado=(int)round(array_sum(array_column($r['pagos'],'cop_monto'))*100);if((int)round($monto*100)>(int)round((float)$r['movimiento']['com_total']*100)-$pagado)throw new InvalidArgumentException('El pago supera el saldo pendiente.');
            $this->q('INSERT INTO movimiento_pago(mov_id,mpa_fecha,tpa_id,mpa_medio,mpa_numero_operacion,cba_id,mpa_monto,mpa_usuario_creacion,mpa_clave) VALUES(?,?,?,?,?,?,?,?,?)',[$id,$fecha,$tpa,$tipo,$op?:null,$cba,$monto,$usu,$clave]);$this->db->commit();
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function anular(int $id,int $usu): void {$this->db->beginTransaction();try{$r=$this->obtener($id,true);$this->activa($r['movimiento']);if(count($r['pagos']))throw new InvalidArgumentException('Anula primero los pagos registrados de este egreso.');$this->q('UPDATE movimiento SET mov_estado=2,mov_usuario_anulacion=?,mov_fecha_anulacion=NOW() WHERE mov_id=?',[$usu,$id]);$this->db->commit();}catch(Throwable $e){$this->db->rollBack();throw $e;}}
    public function anularPago(int $id,int $cop): void {$this->db->beginTransaction();try{$r=$this->obtener($id,true);$this->activa($r['movimiento']);$s=$this->q('UPDATE movimiento_pago SET mpa_estado=2,mpa_usuario_anulacion=?,mpa_fecha_anulacion=NOW() WHERE mpa_id=? AND mov_id=? AND mpa_estado=1',[$_SESSION['usu_id_ifact']??null,$cop,$id]);if(!$s->rowCount())throw new InvalidArgumentException('El pago no está disponible.');$this->db->commit();}catch(Throwable $e){$this->db->rollBack();throw $e;}}
    public static function validarArchivo(array $f): array {
        if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new InvalidArgumentException('Selecciona un archivo válido; verifica el límite de subida del servidor.');
        $path=(string)($f['tmp_name']??'');$size=is_file($path)?filesize($path):0;if(!$size||$size>5*1024*1024)throw new InvalidArgumentException('El archivo debe pesar hasta 5 MB.');
        $mime=(new finfo(FILEINFO_MIME_TYPE))->file($path);$types=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp'];if(!isset($types[$mime]))throw new InvalidArgumentException('Solo se permiten PDF e imágenes JPG, PNG, GIF o WEBP.');
        if($mime==='application/pdf'){if(file_get_contents($path,false,null,0,5)!=='%PDF-')throw new InvalidArgumentException('El PDF no es válido.');}elseif(!@getimagesize($path))throw new InvalidArgumentException('La imagen no es válida.');
        return ['mime'=>$mime,'extension'=>$types[$mime],'size'=>$size];
    }
    public function subir(int $id,int $usu,array $f): void {
        $meta=self::validarArchivo($f);if(!is_uploaded_file($f['tmp_name']))throw new InvalidArgumentException('Subida de archivo inválida.');$name=$this->texto(basename(str_replace('\\','/',(string)$f['name'])),255,'Nombre del archivo');$dir=dirname(__DIR__).'/storage/compras';if(!is_dir($dir)&&!mkdir($dir,0770,true))throw new RuntimeException('No se pudo crear la carpeta de adjuntos.');$rel='storage/compras/'.bin2hex(random_bytes(20)).'.'.$meta['extension'];$path=dirname(__DIR__).'/'.$rel;
        $this->db->beginTransaction();try{$this->activa($this->obtener($id,true)['movimiento']);$documentos=$this->q('SELECT mdo_id FROM movimiento_documento WHERE mov_id=? AND mdo_estado=1 FOR UPDATE',[$id])->fetchAll();if(count($documentos))throw new InvalidArgumentException('El movimiento ya tiene un documento. Elimínalo antes de cargar otro.');if(!move_uploaded_file($f['tmp_name'],$path))throw new RuntimeException('No se pudo guardar el archivo.');$this->q('INSERT INTO movimiento_documento(mov_id,mdo_nombre,mdo_ruta,mdo_usuario_creacion,mdo_mime,mdo_tamano) VALUES(?,?,?,?,?,?)',[$id,$name,$rel,$usu,$meta['mime'],$meta['size']]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if(is_file($path))unlink($path);throw $e;}
    }
    public function documento(int $id,int $doc): array {$this->obtener($id);$d=$this->q('SELECT mdo_nombre cdo_nombre,mdo_ruta cdo_ruta,mdo_mime cdo_mime,mdo_tamano cdo_tamano FROM movimiento_documento WHERE mdo_id=? AND mov_id=? AND mdo_estado=1',[$doc,$id])->fetch();if(!$d)throw new InvalidArgumentException('El documento no está disponible.');$root=dirname(__DIR__);$path=realpath($root.'/'.$d['cdo_ruta']);$allowed=false;foreach([$root.'/storage/compras',$root.'/img/compras'] as $dir){$dir=realpath($dir);if($dir&&$path&&str_starts_with(strtolower($path),strtolower($dir.DIRECTORY_SEPARATOR)))$allowed=true;}if(!$allowed||!is_file($path))throw new InvalidArgumentException('No se encontró el archivo adjunto.');$d['path']=$path;$d['mime']=(new finfo(FILEINFO_MIME_TYPE))->file($path);if(!in_array($d['mime'],['application/pdf','image/jpeg','image/png','image/gif','image/webp'],true))throw new InvalidArgumentException('Formato no permitido.');return $d;}
    public function eliminarDocumento(int $id,int $doc): void {$this->db->beginTransaction();try{$this->activa($this->obtener($id,true)['movimiento']);$s=$this->q('UPDATE movimiento_documento SET mdo_estado=2 WHERE mdo_id=? AND mov_id=? AND mdo_estado=1',[$doc,$id]);if(!$s->rowCount())throw new InvalidArgumentException('El documento no está disponible.');$this->db->commit();}catch(Throwable $e){$this->db->rollBack();throw $e;}}
}
